const vector3df k_gravity = vector3df(0.0f, -9.8f * 3, 0.0f);
const float k_flyingTime = 0.6f;
const float k_maxDamagePerUnit = 9999.0f;
const float k_spriteScale = 1.5f;

const int k_touch_x = 0;
const int k_touch_y = 65;
const int k_touch_w = 80;
const int k_touch_h = 120;

void setAdditive (ISceneNode * node);

class CIceballNode : public CEmptySceneNode
{
public:
	CIceballNode (CIceball* fb)
	{
		m_Iceball = fb;
	}

	~CIceballNode ()
	{
	}

	video::SMaterial& getMaterial(u32 num)
	{
		return *m_Iceball->getSprite()->_material;
	}

	u32 getMaterialCount() const
	{
		return 1;
	}

	void OnRegisterSceneNode ()
	{
		SceneManager->registerNodeForRendering(this, &getMaterial(0), 0, ESNRP_TRANSPARENT);
	}

	void render (void* renderData)
	{
		m_Iceball->draw();
	}

private:
	CIceball* m_Iceball;
};

CIceball::CIceball() : CWeaponObject(0)
{
	m_velocity = vector3df(0.0f, 0.0f, 0.0f);

	m_Node = new CIceballNode(this);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_Node);

	m_postament = LoadColladaScene("Scenes/Fireball/bowl_ice.bdae");
	cleanNode(m_postament);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_postament);

	m_shadow = LoadColladaScene("Scenes/Goblin/shadow.bdae");
	cleanNode(m_shadow);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_shadow);

	m_groundIce = LoadColladaScene("Scenes/Fireball/ice.bdae");
	cleanNode(m_groundIce);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_groundIce);

	m_light = LoadColladaScene("Scenes/Fireball/fireball_light.bdae");
	cleanNode(m_light);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_light);

	array< scene::ISceneNode *> meshnodes;
	m_SceneManager->getSceneNodesFromType(ESNT_LIGHT, meshnodes, m_light);
	u32 i;
	for (i=0; i<meshnodes.size(); i++)
		meshnodes[i]->remove();

	m_sprite = NULL;

	m_spriteGlow = new ASprite;
	m_spriteGlow->Load("Ingame/iceball_glow");
	m_spriteGlow->_material->setMaterialType(EMT_TRANSPARENT_ADD_COLOR);

	m_inst.StartAnim(m_sprite, 0, 0, 0);

	m_touch = new CTouchElement(CTouchElement::Type_Drag, 1000);
	m_touch->SetScreenCoordinates(k_touch_x, k_touch_y, k_touch_w, k_touch_h);

	setLevel(WL_None);
	reset();
}

void CIceball::setSpawnPosition(ISceneNode * node)
{
	node->addChild(m_postament);

	m_spawnPosition = node->getAbsolutePosition() + v3f(0,2,0);
	setPosition(m_spawnPosition);
}

void CIceball::reset()
{
	CWeaponObject::reset();

	if (m_level != WL_None)
	{
		m_sprite->_material->setFlag(EMF_ZBUFFER, false);
		m_spriteGlow->_material->setFlag(EMF_ZBUFFER, false);
		setShouldBeVisible(true, false, false);
		setPosition(m_spawnPosition);
		//setState(IS_RespawningToReadyTransition);
		setState(IS_Ready);
	}
	else
	{
		setState(IS_Disabled);
		setShouldBeVisible(false, false, false);
	}

	setVisible(true);
}

CIceball::~CIceball()
{
	m_Node->remove();
	m_Node->drop();

	m_postament->remove();
	m_postament->drop();

	m_shadow->remove();
	m_shadow->drop();

	m_light->remove();
	m_light->drop();

	m_groundIce->remove();
	m_groundIce->drop();

	SAFE_DEL(m_sprite);
	SAFE_DEL(m_spriteGlow);

	SAFE_DEL(m_touch);
}

void CIceball::adjustStats(IAttributes* attributes)
{
	const char* cooldown[] = { "CooldownEasy", "CooldownMedium", "CooldownHard" };
	int difficulty = (int)(CPlayfield::GetInstance()->getDifficulty());
	m_stat_cooldown =	attributes->getAttributeAsFloat( cooldown[difficulty] );

	m_stat_radius			= attributes->getAttributeAsFloat("DamageRadius");
	m_stat_maxIcedUnits		= attributes->getAttributeAsInt("MaxIcedUnits");
	m_stat_groundIceRadius	= attributes->getAttributeAsFloat("GroundIceRadius");

	if (!m_sprite)
	{
		m_sprite = new ASprite();
		m_sprite->Load("Ingame/iceball");
		m_inst.SetASprite(m_sprite);
	}
	
	switch (m_level)
	{
	case WL_1: m_sprite->LoadTexture("Sprites/Ingame/iceball_small.png"); break;
	case WL_2: m_sprite->LoadTexture("Sprites/Ingame/iceball_medium.png"); break;
	case WL_3: m_sprite->LoadTexture("Sprites/Ingame/iceball_big.png"); break;
	}
}

bool CIceball::isGroundSlippery (v3f pos)
{
	return m_visibleEffect && (m_groundIce->getAbsolutePosition() - pos).getLength() < 0.5f * m_groundIce->getScale().X;
}

void CIceball::update(f32 time)
{
	CWeaponObject::update(time);

	m_drawItems.set_used(0);
	m_stateTime += time;
	m_inst.Update(time);

	m_touch->SetEnabled( isDragable() );

	CPlayfield* playfield = CPlayfield::GetInstance();
	line3df path = playfield->getPath();
	line3df extendedPath = path;
	extendedPath.end += path.getVector().setLength(6.0f);
	vector3df pathDir = path.getVector();

	if (m_groundIceTimer > 0.0f)
	{
		m_groundIceTimer -= time;
		if (m_groundIceTimer < 1.0f)
		{
			float scale = powf(0.001f, time);
			m_groundIce->setScale(m_groundIce->getScale() * scale);
		}
		if (m_groundIceTimer < 0.0f)
		{
			setShouldBeVisible(m_visibleObject, m_visibleShadow, false);
		}
	}

	switch (m_state)
	{
		//enable z write when in Shop and Intro
		case IS_Shop:
			{
				m_sprite->_material->setFlag(EMF_ZBUFFER, true);
				m_spriteGlow->_material->setFlag(EMF_ZBUFFER, true);
			}
		case IS_Intro:
			{
				if ( m_sprite ) 
				{
					if ( m_sprite->_material ) 
						m_sprite->_material->setFlag(EMF_ZBUFFER, true);
				}
				if ( m_spriteGlow ) 
				{
					if ( m_spriteGlow->_material )
						m_spriteGlow->_material->setFlag(EMF_ZBUFFER, true);
				}
			}
		case IS_Ready:
		{
			m_drawItems.push_back(PosScale(getPosition(), k_spriteScale));
			if (m_touch->IsActive())
			{
				PlaySfx( SFX_DEFENSE_ICEBALL_AIM );
				CPlayfield::GetInstance()->getChallenge()->specialWeaponUsed();

				startDrag(m_touch);
				m_velocity = v3f(0,0,0);
				m_smoothVelocity = v3f(0,0,0);
			}
			break;
		}

		case IS_Dragged:
		{
			m_sprite->_material->setFlag(EMF_ZBUFFER, false);
			m_spriteGlow->_material->setFlag(EMF_ZBUFFER, false);

			position2di spawn2d = screenFrom3DPos(m_spawnPosition);
			position2di touch;
			m_touch->GetTouchPos_Current(touch.X, touch.Y);
			touch = touch + m_dragOffset;

			vector2df diff(touch.X - spawn2d.X, touch.Y - spawn2d.Y);
			if (m_touch->IsActive())
			{
				line3df ray = m_SceneManager->getSceneCollisionManager()->getRayFromScreenCoordinates(touch);

				vector3df newPos;
				playfield->getFlyingPlane().getIntersectionWithLine(ray.start, ray.getVector(), newPos);

				if (playfield->getCastlePlane().classifyPointRelation(newPos) != ISREL3D_FRONT)
				{
					playfield->getCastlePlane().getIntersectionWithLine(newPos, path.getVector(), newPos);
				}
				if (playfield->getGroundPlane().classifyPointRelation(newPos) != ISREL3D_FRONT)
				{
					playfield->getGroundPlane().getIntersectionWithLine(newPos, v3f(0,1,0), newPos);
				}

				v3f newVelocity = (newPos - getPosition()) / time;
				if (newVelocity.getLength() > 25.0f)
					newVelocity.setLength(25.0f);
				v3f acceleration = (newVelocity - m_velocity) / time;

				m_velocity = newVelocity;

				float k = powf(0.001f, time);
				m_smoothVelocity = k * m_smoothVelocity + (1 - k) * m_velocity;

				setPosition(getPosition() + m_velocity * time);

				calculateTail(v3f(0, 0, 0), m_smoothVelocity);
			}
			else
			{
				setState(IS_Flying);

				//PlaySfx( SFX_DEFENSE_FIREBALL_FLY );

				calculateTail(v3f(0, 0, 0), m_smoothVelocity);
			}
			break;
		}

		case IS_Flying:
		{
			m_velocity += k_gravity * time;
			vector3df oldPos = getPosition();
			vector3df newPos = getPosition() + m_velocity * time;
			setPosition(newPos);
			//m_cometTail->SetPosition(getPosition());

			calculateTail(k_gravity, m_velocity);

			bool hit = false;

			/// Castle Hit Test
			if (playfield->getCastlePlane().classifyPointRelation(newPos) == ISREL3D_BACK)
			{
				playfield->getCastlePlane().getIntersectionWithLine(oldPos, (newPos - oldPos), newPos);
				setPosition(newPos);
				hit = true;
			}
				
			/// Ground Hit Test
			if (playfield->getGroundPlane().classifyPointRelation(newPos) == ISREL3D_BACK)
			{
				playfield->getGroundPlane().getIntersectionWithLine(oldPos, (newPos - oldPos), newPos);
				setPosition(newPos);
				hit = true;
			}

			if (hit)
			{
				explode();

				PlaySfx( SFX_DEFENSE_ICEBALL_IMPACT );
			}
			break;
		}

		case IS_Dying:
		{
			setShouldBeVisible(true, false, true);

			m_velocity += k_gravity * time;
			vector3df newPos = getPosition() + m_velocity * time;
			setPosition(newPos);
			calculateTail(k_gravity, m_velocity);
			//m_cometTail->SetPosition(getPosition());

			if (m_drawItems.size() == 0)
			{
				//m_cometTail->UnloadParticleSystem();
				setShouldBeVisible(false, false, m_visibleEffect);
				setState(IS_Respawning);
				//RemoveParticleSystem(m_cometTail);
			}
			break;
		}

		case IS_Respawning:
		{
			if (m_stateTime > m_stat_cooldown || CGameConfig::NoWeaponCD)
			{
				m_sprite->_material->setFlag(EMF_ZBUFFER, false);
				m_spriteGlow->_material->setFlag(EMF_ZBUFFER, false);
				setShouldBeVisible(true, false, false);
				setPosition(m_spawnPosition);
				setState(IS_RespawningToReadyTransition);
			}
			break;
		}

		case IS_RespawningToReadyTransition:
		{
			m_drawItems.push_back(PosScale(getPosition() - (0.4f - m_stateTime) * vector3df(0, 2.0f, 0), k_spriteScale * (m_stateTime / 0.4f)));
			if (m_stateTime > 0.4f)
			{
				setState(IS_Ready);
			}
			break;
		}
	}

	if (m_state == IS_Dragged || m_state == IS_Flying)
	{
		v3f pos = getPosition();
		p2i screen = screenFrom3DPos(pos);
		line3df ray = m_SceneManager->getSceneCollisionManager()->getRayFromScreenCoordinates(screen);

		if (playfield->getFlyingPlane().classifyPointRelation(pos) == ISREL3D_BACK)
		{
			playfield->getFlyingPlane().getIntersectionWithLine(ray.start, ray.getVector(), pos);
			setPosition(pos);
		}
	}

	if (m_state == IS_Dragged || m_state == IS_Flying)
	{
		v3f shadowPos;
		playfield->getGroundPlane().getIntersectionWithLine(getPosition(), v3f(0,1,0), shadowPos);
		m_shadow->setPosition(shadowPos);
		m_light->setPosition(shadowPos);
		float distanceFromGround = playfield->getGroundPlane().getDistanceTo(getPosition());
		float scale = 2.0f - 0.1f * distanceFromGround;
		CLAMP(scale, 0.4f, 2.0f);
		m_shadow->setScale(v3f(scale, scale, scale));
		m_light->setScale(2.0f * v3f(scale, scale, scale));
	}
}

void CIceball::elfArrowHit ()
{
	if (m_state == IS_Ready)
	{
		setShouldBeVisible(false, false, false);
		setState(IS_Respawning);

		PlaySfx( SFX_ATTACK_SABOTAGE_WEAPON );
	}
}

